import { defineConfig, memoryCache } from 'astro/config';
import node from '@astrojs/node';

export default defineConfig({
  output: 'server',
  adapter: node({ mode: 'standalone' }),
  server: { host: '0.0.0.0' },
  cache: { provider: memoryCache() },
});

// src/pages/api/revalidate.ts
import type { APIRoute } from 'astro';
import { sheetCache } from '../../lib/cache';

export const POST: APIRoute = async (context) => {
  if (context.request.headers.get('authorization') !== `Bearer ${import.meta.env.REVALIDATE_TOKEN}`) {
    return new Response('unauthorized', { status: 401 });
  }
  sheetCache.bust();                                   // data-level TTL cache (single process => exact)
  await context.cache.invalidate({ tags: ['sheet'] }); // Astro 7 route cache, memoryCache provider
  return new Response(null, { status: 204 });
};
